import { Page } from "@playwright/test";
import { BasePage } from "./BasePage";

// Generated by Tracewright from the Phase 1 page-object registry; every locator below
// was verified against the live app. Regenerate instead of editing by hand.
export class LoginPage extends BasePage {
  readonly url_pattern = "http://localhost:4000/login";

  constructor(page: Page) {
    super(page);
  }

  get loginHeading() {
    return this.page.getByRole("heading", { name: "Log In" });
  }

  get emailInput() {
    return this.page.getByRole("textbox", { name: "Email" });
  }

  get passwordInput() {
    return this.page.getByTestId("login-password");
  }

  get loginButton() {
    return this.page.getByRole("button", { name: "Log in" });
  }

  // Exists only after: "open http://localhost:4000/login; fill Email with nobody@example.com; fill login-password with wrong-password; click Log in"
  get loginErrorAlert() {
    return this.page.getByRole("alert");
  }
}
